from pathlib import Path

p = Path('project110-preview/app/src/main/java/com/offlineai/app/MainActivity.kt')
s = p.read_text()
needle = '''        restoreModel()\n    }\n\n    private fun registerDownloadReceiver()'''
hook = '''        restoreModel()\n        when {\n            intent.getBooleanExtra("__theme_preserve_test", false) -> {\n                switchToConversation()\n                currentChatLines.clear()\n                currentChatLines += ChatLine("user", "BUILD110_TEMA_KORUMA_KULLANICI")\n                currentChatLines += ChatLine("assistant", "BUILD110_TEMA_KORUMA_ASISTAN")\n                renderCurrentChatLines()\n                input.setText("BUILD110_TASLAK_KORUNDU")\n                root.postDelayed({ toggleTheme() }, 5000L)\n            }\n            intent.getBooleanExtra("__scroll_stream_test", false) -> {\n                switchToConversation()\n                addUserBubble("BUILD110 uzun yanıt kaydırma testi")\n                root.postDelayed({\n                    conversationScroll.setOnScrollChangeListener { _, _, scrollY, _, oldScrollY ->\n                        android.util.Log.d("BUILD110_SCROLL", "old=$oldScrollY y=$scrollY")\n                    }\n                    val assistant = addAssistantMessage()\n                    assistant.thinking.stopAndHide()\n                    assistant.answer.visibility = View.VISIBLE\n                    scrollToBottom(force = true)\n                    val typing = TypingSession(this@MainActivity, assistant.answer) { scrollToBottom(force = false) }\n                    launch {\n                        repeat(50) { index ->\n                            typing.append("Akış ${index + 1}: Uzun yanıt emülatör üzerinde gerçek zamanlı yazılıyor ve ekranın aşağı doğru kararlı biçimde ilerlemesi gerekiyor. ")\n                            delay(18L)\n                        }\n                        typing.complete()\n                        typing.awaitFinished()\n                        android.util.Log.d("BUILD110_SCROLL", "DONE y=${conversationScroll.scrollY}")\n                    }\n                }, 800L)\n            }\n            intent.getBooleanExtra("__about_test", false) -> {\n                root.postDelayed({ showAbout() }, 1000L)\n            }\n        }\n    }\n\n    private fun registerDownloadReceiver()'''
if needle not in s:
    raise SystemExit('BUILD110 preview hook anchor not found')
p.write_text(s.replace(needle, hook, 1))
